const paths={home:'M3 10 12 3l9 7v11h-6v-7H9v7H3z',cart:'M3 3h2l3 12h10l3-8H6 M9 20h.01 M18 20h.01',box:'m3 7 9-4 9 4v10l-9 4-9-4z M3 7l9 4 9-4 M12 11v10',bag:'M5 7h14l1 14H4z M9 7V5a3 3 0 0 1 6 0v2',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M17 4a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87',wallet:'M20 7H4V4h14v3 M3 7h18v14H3z M16 12h5v5h-5z',chart:'M4 3v18h18 M8 16v-4 M13 16V8 M18 16V5',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z',search:'M21 21l-5-5 M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M14 7l5 5-5 5',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',diamond:'m3 8 4-5h10l4 5-9 13z M3 8h18 M7 3l5 18 5-18',clock:'M12 8v5l3 2 M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20',check:'m5 12 4 4L19 6',alert:'m12 3 10 18H2z M12 9v4 M12 17h.01',close:'m6 6 12 12 M6 18 18 6',download:'M12 3v12 m-5-5 5 5 5-5 M4 16v5h16v-5',menu:'M3 6h18 M3 12h18 M3 18h18',receipt:'M5 3h14v18l-3-2-4 2-4-2-3 2z M8 8h8 M8 12h8',lock:'M5 10h14v11H5z M8 10V6a4 4 0 0 1 8 0v4',print:'M6 8V3h12v5 M6 17H3V9h18v8h-3 M6 14h12v7H6z',back:'M19 12H5 m5-5-5 5 5 5',logout:'M9 3H3v18h6 M9 12h12 m-5-5 5 5-5 5',store:'M3 9 5 3h14l2 6 M3 9v12h18V9 M8 21v-8h8v8',edit:'m16 3 5 5-12 12-6 1 1-6z M14 5l5 5'};
const icon=(name,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.diamond}"/></svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>n===null?'Costo histórico pendiente':'$ '+Math.round(Number(n)||0).toLocaleString('es-CO');
const grams=n=>Number(n).toLocaleString('es-CO',{minimumFractionDigits:2,maximumFractionDigits:6})+' g';
function jewel(p){let shape=p.type==='ring'?'<ellipse cx="60" cy="71" rx="29" ry="31"/><ellipse cx="60" cy="71" rx="23" ry="25"/><path d="m43 37 9-12h16l9 12-17 17z M43 37h34 M52 25l8 29 8-29"/>':p.type==='chain'?'<path d="M20 25c0 86 80 86 80 0 M25 25c0 78 70 78 70 0"/><path d="m48 88 12 15 12-15-12-12z"/><path d="M21 35h6m-4 11 6-2m-2 12 6-3m-1 12 5-5m1 13 4-5m4 13 2-6m8 11v-6m13 5-2-6m12-1-4-5m13-4-5-5m10-7-6-3m9-9-6-2m8-11h-6"/>':p.type==='earrings'?'<ellipse cx="37" cy="62" rx="19" ry="34"/><ellipse cx="83" cy="62" rx="19" ry="34"/><ellipse cx="37" cy="62" rx="14" ry="29"/><ellipse cx="83" cy="62" rx="14" ry="29"/>':'<path d="M60 92 24 57c-22-26 16-49 36-21 20-28 58-5 36 21z"/><ellipse cx="60" cy="24" rx="5" ry="8"/>';
return `<div class="jewel ${p.metal.includes('Plata')?'silver':''}"><span class="tag">${esc(p.metal)}</span><svg viewBox="0 0 120 120" fill="none" stroke="currentColor" aria-hidden="true">${shape}</svg></div>`;}
